"""SQLite-backed storage for tally entries.

The on-disk format is a SQLite database, but ``export_json()`` still writes
the same JSON array the downstream reporting script expects. A pre-existing
legacy JSON file at ``path`` is migrated into SQLite on first open.
"""
from __future__ import annotations

import json
import sqlite3
from contextlib import closing
from pathlib import Path
from typing import Dict, List

_SQLITE_MAGIC = b"SQLite format 3\x00"


class Store:
    def __init__(self, path: str | Path = "tally.json") -> None:
        self.path = Path(path)
        legacy_entries = self._read_legacy_json()
        with closing(self._connect()) as conn, conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS entries ("
                " id INTEGER PRIMARY KEY AUTOINCREMENT,"
                " amount REAL NOT NULL,"
                " note TEXT NOT NULL DEFAULT '')"
            )
            if legacy_entries:
                conn.executemany(
                    "INSERT INTO entries (amount, note) VALUES (?, ?)",
                    [(float(e["amount"]), e.get("note", "")) for e in legacy_entries],
                )

    def add(self, amount: float, note: str = "") -> Dict:
        amount = float(amount)
        if amount < 0:
            raise ValueError(f"amount must be non-negative, got {amount}")
        with closing(self._connect()) as conn, conn:
            conn.execute(
                "INSERT INTO entries (amount, note) VALUES (?, ?)", (amount, note)
            )
        return {"amount": amount, "note": note}

    def entries(self) -> List[Dict]:
        with closing(self._connect()) as conn:
            rows = conn.execute(
                "SELECT amount, note FROM entries ORDER BY id"
            ).fetchall()
        return [{"amount": amount, "note": note} for amount, note in rows]

    def total(self) -> float:
        return round(sum(e["amount"] for e in self.entries()), 2)

    def export_json(self, out_path: str | Path) -> Path:
        """Write all entries as a JSON array. The reporting script reads this."""
        out = Path(out_path)
        out.write_text(json.dumps(self.entries(), indent=2), encoding="utf-8")
        return out

    def _connect(self) -> sqlite3.Connection:
        return sqlite3.connect(self.path)

    def _read_legacy_json(self) -> List[Dict]:
        """Return entries from a pre-SQLite JSON file at ``self.path``, removing it.

        The caller re-inserts them into the fresh database created in its place.
        """
        if not self.path.exists() or self.path.stat().st_size == 0:
            return []
        with self.path.open("rb") as f:
            if f.read(len(_SQLITE_MAGIC)) == _SQLITE_MAGIC:
                return []
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"{self.path} is neither a SQLite database nor a tally JSON file"
            ) from exc
        if not isinstance(data, list):
            raise ValueError(f"{self.path} does not contain a tally entry list")
        self.path.unlink()
        return data

